# ==============================================================================
# aerc Notmuch Query Map for Global "All" Mailbox
# ==============================================================================
Inbox = folder:"/^.*\/INBOX$/"
Unread = folder:"/^.*\/INBOX$/" and tag:unread
Starred = tag:flagged
Sent = folder:"/^.*(\/Sent|\/Sent Messages|\/Posta inviata)$/"
Drafts = folder:"/^.*(\/Drafts|\/Draft|\/draft|\/Bozze)$/"
Archive = folder:"/^.*(\/Archivio|\/Archive|\/Tutti i messaggi)$/"
Spam = folder:"/^.*(\/Junk|\/Spam|\/Bulk)$/"
Trash = folder:"/^.*(\/Trash|\/trash|\/Deleted|\/Deleted Messages|\/Cestino)$/"
